// Logo d'en-tête pour les documents imprimés (bons de sortie, fiches
// parcellaires, confirmations d'achat, etc.) — logo ROPAMIL fourni le 2026-07-10.
export const PRINT_LOGO_DATA_URL = 'data:image/svg+xml;base64,'

export function printLogoHtml(maxHeight = 42) {
  if (!PRINT_LOGO_DATA_URL) return ''
  return `<img src="${PRINT_LOGO_DATA_URL}" style="max-height:${maxHeight}px;display:block;" />`
}
